DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 18;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _scope_unretire_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'D58 D50 scope unretire: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _scope_unretire_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'scope_status' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'scope_reason' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text OR p.old_value IS NULL OR p.new_value IS NULL
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D58 D50 scope unretire: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _scope_unretire_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'scope_status' THEN u.scope_status IS DISTINCT FROM p.old_value::text
                WHEN 'scope_reason' THEN u.scope_reason IS DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D58 D50 scope unretire: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row undos a value this lane owns (old value)
    SELECT count(*) INTO bad FROM _scope_unretire_plan p
     WHERE CASE p.column_name
                WHEN 'scope_status' THEN p.old_value NOT IN ('in_scope')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D58 D50 scope unretire: % planned row(s) undo a value this lane does not own', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _scope_unretire_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (concat_ws(' | ', u.name, coalesce(u.site_type, 'NULL'), u.lat::text, u.lon::text, coalesce(u.country, 'NULL'), coalesce(u.period_start::text, 'NULL'), coalesce(u.period_end::text, 'NULL'), md5(coalesce(u.description, '')), md5(coalesce((SELECT cs.card_description FROM card_stats cs WHERE cs.site_id = u.id), '')))) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D58 D50 scope unretire: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _scope_unretire_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'D58/scope-unretire', '2026-10-24_mechanical-scope-unretire-rollback', r.change_key, 'authoritative', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'D58 D50 scope unretire: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _scope_unretire_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'scope_status' THEN u.scope_status IS DISTINCT FROM p.new_value::text
                WHEN 'scope_reason' THEN u.scope_reason IS DISTINCT FROM p.new_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D58 D50 scope unretire: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _scope_unretire_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-10-24_mechanical-scope-unretire-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D58 D50 scope unretire: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-10-24_mechanical-scope-unretire-rollback'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('scope_status', 'scope_reason'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'D58 D50 scope unretire: this run stamp journalled % row(s) outside unified_sites.(scope_status, scope_reason)', bad;
    END IF;

    RAISE NOTICE 'D58 D50 scope unretire: % of % planned cell(s) changed and journalled over 9 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
